#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# Grava sempre no .env ao lado deste script (backend/.env), de onde quer que rode.
ENV_FILE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/.env"
TOTAL_STAGES=5

# gera um segredo aleatorio (openssl ou fallback)
_rand() { openssl rand -hex 32 2>/dev/null || head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n'; }

banner "MFA-login · chaves OAuth (Google, Microsoft, Apple)"

# ── 1. Segredos locais e URL base ─────────────────────────────────────────
stage "Segredos locais e URL do backend"
say "Primeiro os segredos do JWT (gerados automaticamente se ainda nao existirem)."
for k in JWT_SECRET MFA_TOKEN_SECRET; do
  if [[ -z "$(_existing "$k" || true)" ]]; then write_env "$k" "$(_rand)"; else note "$k ja existe, mantendo"; fi
done
[[ -z "$(_existing PORT || true)" ]]         && write_env PORT 3000
[[ -z "$(_existing JWT_EXPIRES || true)" ]]  && write_env JWT_EXPIRES 15m
[[ -z "$(_existing MFA_ISSUER || true)" ]]   && write_env MFA_ISSUER MeuApp
[[ -z "$(_existing FRONTEND_URL || true)" ]] && write_env FRONTEND_URL http://localhost:5173
printf '\n'
say "Agora a URL publica do backend. Ela define as URLs de callback que voce vai"
say "cadastrar em cada console, entao precisa bater exatamente."
note "Local: http://localhost:3000   |   Tunel (celular/Apple): https://xxxx.trycloudflare.com"
note "Com tunel, o Vite faz proxy de /auth, entao use a URL do tunel do FRONT."
ask BACKEND_URL "URL do backend (Enter = http://localhost:3000):"
BACKEND_URL="${BACKEND_URL:-http://localhost:3000}"
BACKEND_URL="${BACKEND_URL%/}"
write_env BACKEND_URL "$BACKEND_URL"
printf '\n'
say "Callbacks que vao ser usados:"
note "  Google:    $BACKEND_URL/auth/google/callback"
note "  Microsoft: $BACKEND_URL/auth/microsoft/callback"
note "  Apple:     $BACKEND_URL/auth/apple/callback"
pause

# ── 2. Google ─────────────────────────────────────────────────────────────
stage "Google · OAuth Client"
if confirm "Configurar login com Google agora?"; then
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Selecione (ou crie) um projeto no topo da pagina."
  step "Se pedir, configure a 'Tela de consentimento OAuth' (External, nome do app, seu email). Salve."
  step "Clique '+ Criar credenciais' -> 'ID do cliente OAuth' -> tipo 'Aplicativo da Web'."
  step "Em 'Origens JavaScript autorizadas' adicione: ${BACKEND_URL}"
  step "Em 'URIs de redirecionamento autorizados' adicione EXATAMENTE:"
  say  "    ${BOLD}${BACKEND_URL}/auth/google/callback${RESET}"
  step "Clique 'Criar'. Vai abrir um modal com ID do cliente e Chave secreta."
  ask GOOGLE_CLIENT_ID "Cole o ID do cliente (termina em .apps.googleusercontent.com):"
  ask_secret GOOGLE_CLIENT_SECRET "Cole a Chave secreta do cliente (GOCSPX-...):"
  write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
  write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
  note "Dica: enquanto o app estiver em 'Testing' na tela de consentimento, so emails"
  note "adicionados como 'Test users' conseguem logar."
else
  SKIPPED+=("Google: rode de novo quando quiser configurar")
fi
pause

# ── 3. Microsoft ──────────────────────────────────────────────────────────
stage "Microsoft · App registration (Entra ID)"
if confirm "Configurar login com Microsoft agora?"; then
  open_url "https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade"
  step "Clique '+ New registration'."
  step "Nome: o do seu app."
  step "Supported account types: 'Accounts in any organizational directory and personal Microsoft accounts'"
  say  "    (isso e o tenant 'common': aceita conta corporativa e pessoal)."
  step "Redirect URI: plataforma 'Web', valor EXATO:"
  say  "    ${BOLD}${BACKEND_URL}/auth/microsoft/callback${RESET}"
  step "Clique 'Register'. Na pagina Overview copie o 'Application (client) ID'."
  ask MICROSOFT_CLIENT_ID "Cole o Application (client) ID:"
  step "Menu lateral -> 'Certificates & secrets' -> '+ New client secret' -> descricao e validade -> 'Add'."
  step "Copie a coluna ${BOLD}Value${RESET} (nao o Secret ID). Ela so aparece uma vez."
  ask_secret MICROSOFT_CLIENT_SECRET "Cole o Value do client secret:"
  ask MICROSOFT_TENANT "Tenant (Enter = common):"
  MICROSOFT_TENANT="${MICROSOFT_TENANT:-common}"
  write_env MICROSOFT_CLIENT_ID "$MICROSOFT_CLIENT_ID"
  write_env MICROSOFT_CLIENT_SECRET "$MICROSOFT_CLIENT_SECRET"
  write_env MICROSOFT_TENANT "$MICROSOFT_TENANT"
else
  SKIPPED+=("Microsoft: rode de novo quando quiser configurar")
fi
pause

# ── 4. Apple ──────────────────────────────────────────────────────────────
stage "Apple · Sign in with Apple"
warn "Requer Apple Developer Program (pago) e callback HTTPS com dominio real."
warn "Nao funciona com http://localhost. Use a URL do tunel ou do seu dominio."
if [[ "$BACKEND_URL" == http://* ]]; then
  warn "BACKEND_URL atual e http ($BACKEND_URL). A Apple vai recusar esse callback."
fi
if confirm "Configurar login com Apple agora?"; then
  open_url "https://developer.apple.com/account/resources/identifiers/list"
  step "1/3 App ID: '+' -> 'App IDs' -> 'App' -> descricao + Bundle ID (ex: com.seuapp.ios)."
  step "    Em Capabilities marque 'Sign In with Apple'. Continue -> Register."
  pause "App ID criado? [Enter]"
  open_url "https://developer.apple.com/account/resources/identifiers/list/serviceId"
  step "2/3 Services ID: '+' -> 'Services IDs' -> descricao + Identifier (ex: com.seuapp.web)."
  step "    Register. Depois abra o Services ID criado e marque 'Sign In with Apple' -> Configure."
  step "    Primary App ID: o App ID do passo anterior."
  step "    Domains: o host de ${BACKEND_URL} (sem https://)."
  step "    Return URLs, EXATO:"
  say  "    ${BOLD}${BACKEND_URL}/auth/apple/callback${RESET}"
  step "    Save -> Continue -> Save."
  ask APPLE_CLIENT_ID "Cole o Identifier do Services ID (ex: com.seuapp.web):"
  open_url "https://developer.apple.com/account/resources/authkeys/list"
  step "3/3 Key: '+' -> nome -> marque 'Sign In with Apple' -> Configure -> escolha o App ID -> Save."
  step "    Continue -> Register -> ${BOLD}Download${RESET} (arquivo AuthKey_XXXXXXXXXX.p8, baixa UMA vez so)."
  step "    O 'Key ID' aparece nessa tela."
  ask APPLE_KEY_ID "Cole o Key ID (10 caracteres):"
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  step "Team ID esta em Membership details."
  ask APPLE_TEAM_ID "Cole o Team ID (10 caracteres):"
  step "Caminho do arquivo .p8 baixado (pode arrastar o arquivo pro terminal)."
  ask APPLE_P8_PATH "Caminho do AuthKey_*.p8:"
  APPLE_P8_PATH="$(printf '%s' "$APPLE_P8_PATH" | tr -d "\"'")"
  if command -v cygpath >/dev/null 2>&1; then APPLE_P8_PATH="$(cygpath -u "$APPLE_P8_PATH")"; fi
  if [[ -f "$APPLE_P8_PATH" ]]; then
    # converte o .p8 multi-linha em uma linha com \n literal (a strategy desfaz isso)
    APPLE_PRIVATE_KEY="$(awk 'BEGIN{ORS="\\n"} {print}' "$APPLE_P8_PATH")"
    write_env APPLE_CLIENT_ID "$APPLE_CLIENT_ID"
    write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"
    write_env APPLE_KEY_ID "$APPLE_KEY_ID"
    write_env APPLE_PRIVATE_KEY "$APPLE_PRIVATE_KEY"
    note "Guarde o .p8 em lugar seguro e NAO commite."
  else
    warn "Arquivo nao encontrado: $APPLE_P8_PATH"
    SKIPPED+=("Apple: APPLE_PRIVATE_KEY nao gravada (arquivo .p8 nao encontrado)")
  fi
else
  SKIPPED+=("Apple: rode de novo quando quiser configurar")
fi
pause

# ── 5. Conferencia ────────────────────────────────────────────────────────
stage "Conferencia"
say "Resumo do que esta no $ENV_FILE:"
for k in BACKEND_URL FRONTEND_URL GOOGLE_CLIENT_ID MICROSOFT_CLIENT_ID MICROSOFT_TENANT APPLE_CLIENT_ID APPLE_TEAM_ID APPLE_KEY_ID; do
  v="$(_existing "$k" || true)"
  if [[ -n "$v" ]]; then printf '  %s+%s %-24s %s\n' "$GREEN" "$RESET" "$k" "$v"; else printf '  %s.%s %-24s (vazio)\n' "$DIM" "$RESET" "$k"; fi
done
for k in GOOGLE_CLIENT_SECRET MICROSOFT_CLIENT_SECRET APPLE_PRIVATE_KEY JWT_SECRET MFA_TOKEN_SECRET; do
  if [[ -n "$(_existing "$k" || true)" ]]; then printf '  %s+%s %-24s (oculto)\n' "$GREEN" "$RESET" "$k"; else printf '  %s.%s %-24s (vazio)\n' "$DIM" "$RESET" "$k"; fi
done
printf '\n'
say "Proximo passo: reinicie o backend (npm run start:dev) e clique nos botoes sociais."
say "Se mudar BACKEND_URL (ex: novo tunel), rode este wizard de novo e atualize os callbacks nos consoles."
pause

finish
